package main

import (
	"bytes"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"strings"
	"time"

	"github.com/labstack/echo/v4"
	"golang.org/x/net/html"
)

// Request body
type PreviewRequest struct {
	URL string `json:"url"`
}

// Response body
type PreviewResponse struct {
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
}

// constants
const (
	maxBodySize    = 1 << 20 // 1 MB
	requestTimeout = 3 * time.Second
	userAgent      = "Mozilla/5.0 (compatible; URLPreviewBot/1.0)"
)

func isUnsafeIP(ip net.IP) bool {
	return ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsUnspecified()
}

// isSafeHost checks if the host resolves to a safe (non-internal) IP address.
func isSafeHost(host string) bool {
	// If host is an IP literal.
	if ip := net.ParseIP(host); ip != nil {
		return !isUnsafeIP(ip)
	}
	// Otherwise resolve.
	ips, err := net.LookupIP(host)
	if err != nil {
		return false
	}
	for _, ip := range ips {
		if isUnsafeIP(ip) {
			return false
		}
	}
	return true
}

func FetchURLPreview(ctx echo.Context) error {
	req := new(PreviewRequest)
	if err := ctx.Bind(req); err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Invalid JSON"})
	}

	// Validate URL
	parsedURL, err := url.Parse(req.URL)
	if err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Invalid URL format"})
	}

	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Only HTTP/HTTPS URLs are allowed"})
	}

	// Validate host against SSRF
	host := parsedURL.Hostname()
	if !isSafeHost(host) {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Access to internal URLs is not allowed"})
	}

	// Create HTTP request with context
	httpReq, err := http.NewRequestWithContext(ctx.Request().Context(), http.MethodGet, parsedURL.String(), nil)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to create request"})
	}
	httpReq.Header.Set("User-Agent", userAgent)

	client := &http.Client{Timeout: requestTimeout}
	resp, err := client.Do(httpReq)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to fetch URL"})
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": fmt.Sprintf("HTTP %d", resp.StatusCode)})
	}

	// Read limited body
	limitedReader := io.LimitReader(resp.Body, maxBodySize)
	body, err := io.ReadAll(limitedReader)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to read response body"})
	}

	title, description := extractTitleAndDescription(body)

	return ctx.JSON(http.StatusOK, PreviewResponse{
		Title:       title,
		Description: description,
	})
}

func extractTitleAndDescription(htmlContent []byte) (string, string) {
	title := ""
	description := ""

	z := html.NewTokenizer(bytes.NewReader(htmlContent))
	for {
		tt := z.Next()
		switch tt {
		case html.ErrorToken:
			return title, description
		case html.StartTagToken, html.SelfClosingTagToken:
			tagName, hasAttr := z.TagName()
			if bytes.Equal(tagName, []byte("title")) {
				// Next token should be text inside title
				z.Next()
				if z.Token().Type == html.TextToken {
					title = string(z.Text())
				}
			} else if bytes.Equal(tagName, []byte("meta")) && hasAttr {
				var name, content string
				for {
					key, val, more := z.TagAttr()
					if bytes.Equal(key, []byte("name")) {
						name = string(val)
					} else if bytes.Equal(key, []byte("content")) {
						content = string(val)
					}
					if !more {
						break
					}
				}
				if strings.EqualFold(name, "description") && content != "" {
					description = content
				}
			}
		}
	}
}

