    URL string `json:"url"`
}

// PreviewResponse represents the JSON response sent back to the client.
type PreviewResponse struct {
    URL         string `json:"url"`
    Title       string `json:"title"`
    Description string `json:"description"`
}

// FetchURLPreview handles POST /preview requests.
// It fetches the given URL with a 3‑second timeout, extracts the page title and
// meta description, and returns them as JSON.
func FetchURLPreview(c echo.Context) error {
    var req PreviewRequest
    if err := c.Bind(&req); err != nil {
        return c.JSON(http.StatusBadRequest, map[string]string{"error": "Invalid request payload"})
    }
    if req.URL == "" {
        return c.JSON(http.StatusBadRequest, map[string]string{"error": "URL is required"})
    }

    // Fetch the URL with a 3‑second timeout.
    client := &http.Client{Timeout: 3 * time.Second}
    resp, err := client.Get(req.URL)
    if err != nil {
        return c.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to fetch URL: " + err.Error()})
    }
    defer resp.Body.Close()

    if resp.StatusCode != http.StatusOK {
        return c.JSON(http.StatusInternalServerError, map[string]string{"error": "URL returned non‑200 status"})
    }

    // Parse the HTML document.
    doc, err := html.Parse(resp.Body)
    if err != nil {
        return c.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to parse HTML"})
    }

    title := extractTitle(doc)
    desc := extractMetaDescription(doc)

    return c.JSON(http.StatusOK, PreviewResponse{
        URL:         req.URL,
        Title:       title,
        Description: desc,
    })
}

// getTextContent recursively collects all text inside the subtree rooted at n.
func getTextContent(n *html.Node) string {
    if n.Type == html.TextNode {
        return n.Data
    }
    var sb strings.Builder
    for c := n.FirstChild; c != nil; c = c.NextSibling {
        sb.WriteString(getTextContent(c))
    }
    return sb.String()
}

// extractTitle searches the HTML tree for the first <title> element and returns
// its inner text (trimmed of whitespace).
func extractTitle(n *html.Node) string {
    if n.Type == html.ElementNode && n.Data == "title" {
        return strings.TrimSpace(getTextContent(n))
    }
    for c := n.FirstChild; c != nil; c = c.NextSibling {
        if title := extractTitle(c); title != "" {
            return title
        }
    }
    return ""
}

// extractMetaDescription searches the HTML tree for a <meta name="description">
// tag and returns the value of its "content" attribute.
func extractMetaDescription(n *html.Node) string {
    if n.Type == html.ElementNode && n.Data == "meta" {
        var name, content string
        for _, attr := range n.Attr {
            switch attr.Key {
            case "name":
                name = attr.Val
            case "content":
                content = attr.Val
            }
        }
        if strings.EqualFold(name, "description") {
            return content
        }
    }
    for c := n.FirstChild; c != nil; c = c.NextSibling {
        if desc := extractMetaDescription(c); desc != "" {
            return desc
        }
    }
    return ""
}

func main() {
    e := echo.New()
    e.POST("/preview", FetchURLPreview)
    e.Logger.Fatal(e.Start(":1323"))
}

