// isPrivateIP checks if an IP address is in a private, loopback, link-local, or multicast range.
func isPrivateIP(ip net.IP) bool {
	if ip == nil {
		return true
	}
	if ip.IsLoopback() {
		return true
	}
	if ip.IsPrivate() {
		return true
	}
	if ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
		return true
	}
	if ip.IsMulticast() {
		return true
	}
	if ip.IsUnspecified() {
		return true
	}
	return false
}

// validateHostResolvesToPublicIP resolves a hostname and ensures it does not point to a private IP.
func validateHostResolvesToPublicIP(hostname string) error {
	host, _, err := net.SplitHostPort(hostname)
	if err != nil {
		host = hostname
	}
	ips, err := net.LookupIP(host)
	if err != nil {
		return fmt.Errorf("failed to resolve host: %w", err)
	}
	if len(ips) == 0 {
		return fmt.Errorf("host resolved to no IPs")
	}
	for _, ip := range ips {
		if isPrivateIP(ip) {
			return fmt.Errorf("host resolves to a private/internal IP address: %s", ip)
		}
	}
	return nil
}

// safeDialContext is a custom dial function that validates the resolved IP before connecting.
func safeDialContext(ctx context.Context, network, addr string) (net.Conn, error) {
	dialer := &net.Dialer{
		Timeout: dialTimeout,
	}
	if err := validateHostResolvesToPublicIP(addr); err != nil {
		return nil, err
	}
	return dialer.DialContext(ctx, network, addr)
}

// safeTransport returns an http.Transport with custom dial context that blocks private IPs.
func safeTransport() *http.Transport {
	return &http.Transport{
