// FetchURLPreview handles POST /preview
func FetchURLPreview(ctx echo.Context) error {
    // Parse request body
    var req RequestBody
    if err := ctx.Bind(&req); err != nil {
        return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Invalid request body"})
    }
    if req.URL == "" {
        return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "URL is required"})
    }

    // Create HTTP client with 3-second timeout
    client := &http.Client{
        Timeout: 3 * time.Second,
    }

    // Fetch the URL
    resp, err := client.Get(req.URL)
    if err != nil {
        return ctx.JSON(http.StatusBadGateway, map[string]string{"error": "Failed to fetch URL: " + err.Error()})
    }
    defer resp.Body.Close()

    // Read body up to a reasonable limit (prevent huge downloads)
    body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20)) // 1 MB limit
    if err != nil {
        return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to read response body"})
    }

    // Parse HTML and extract metadata
    preview := extractPreview(body)

    return ctx.JSON(http.StatusOK, preview)
}

// extractPreview parses HTML and extracts title and meta description
func extractPreview(htmlContent []byte) PreviewResponse {
    var title, description string
    tokenizer := html.NewTokenizer(bytes.NewReader(htmlContent))
    inTitle := false

    for {
        tt := tokenizer.Next()
        switch tt {
        case html.ErrorToken:
            // End of document or error
            return PreviewResponse{Title: title, Description: description}
        case html.StartTagToken, html.SelfClosingTagToken:
            tn, hasAttr := tokenizer.TagName()
            tag := string(tn)

            if tag == "title" {
                inTitle = true
            } else if tag == "meta" && hasAttr {
                // Parse attributes to find description
                var name, content string
                for {
                    key, val, more := tokenizer.TagAttr()
                    k := string(key)
                    v := string(val)
                    if k == "name" {
                        name = v
                    } else if k == "content" {
                        content = v
                    }
                    if !more {
                        break
                    }
                }
                if name == "description" {
                    description = content
                }
            }
        case html.TextToken:
            if inTitle {
                title = string(tokenizer.Text())
                inTitle = false
            }
        case html.EndTagToken:
            tn, _ := tokenizer.TagName()
            if string(tn) == "title" {
                inTitle = false
            }
        }
    }
}

func main() {
