// safeDialContext resolves the host and rejects connections to unsafe IPs.
func safeDialContext(ctx context.Context, network, addr string) (net.Conn, error) {
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, err
	}

	// Resolve IPs for the hostname using the request's context (timeouts etc.)
	ips, err := net.DefaultResolver.LookupIPAddr(ctx, host)
	if err != nil {
		return nil, fmt.Errorf("failed to resolve host %s: %w", host, err)
	}

	for _, ip := range ips {
		if isUnsafeIP(ip.IP) {
			return nil, fmt.Errorf("connection to unsafe IP %s is forbidden", ip.IP)
		}
	}

	dialer := &net.Dialer{}
	return dialer.DialContext(ctx, network, net.JoinHostPort(host, port))
