			switch string(tagName) {
			case "title":
				inTitle = true
			case "meta":
				if !hasAttr {
					continue
				}
				var name, content string
				for {
					key, val, more := tokenizer.TagAttr()
					k := string(key)
					v := string(val)
					if k == "name" {
						name = v
					} else if k == "content" {
