					}
					if !more {
						break
					}
				}
				if strings.EqualFold(name, "description") && content != "" {
					description = content
				}
			}
		case html.TextToken:
			if inTitle {
				title = strings.TrimSpace(string(tokenizer.Text()))
				inTitle = false
			}
		}
	}

	return title, description
}

