package main

import (
	"context"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"time"

	"github.com/labstack/echo/v4"
	"golang.org/x/net/html"
)

// Request body
type PreviewRequest struct {
	URL string `json:"url"`
}

// Response body
type PreviewResponse struct {
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
}

const maxBodySize = 2 * 1024 * 1024 // 2 MB

func main() {
	e := echo.New()
	e.POST("/preview", FetchURLPreview)
	e.Logger.Fatal(e.Start(":8080"))
}

// FetchURLPreview handles POST /preview requests.
func FetchURLPreview(ctx echo.Context) error {
	req := new(PreviewRequest)
	if err := ctx.Bind(req); err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Invalid JSON"})
	}

	// Validate URL
	parsedURL, err := parseAndValidateURL(req.URL)
	if err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": err.Error()})
	}

	// Build a custom HTTP client that rejects private/reserved IPs at connection time
	client := &http.Client{
		Transport: &http.Transport{
			DialContext: publicOnlyDialContext(),
		},
	}

	// Set a timeout via context tied to the incoming request
	fetchCtx, cancel := context.WithTimeout(ctx.Request().Context(), 3*time.Second)
	defer cancel()

	httpReq, err := http.NewRequestWithContext(fetchCtx, http.MethodGet, parsedURL.String(), nil)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to create request"})
	}
	httpReq.Header.Set("User-Agent", "Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	resp, err := client.Do(httpReq)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to fetch URL"})
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{
			"error": fmt.Sprintf("HTTP %d", resp.StatusCode),
		})
	}

	// Limit the amount of data we read to avoid resource exhaustion
	limitedReader := io.LimitReader(resp.Body, maxBodySize)
	title, description := extractTitleAndDescription(limitedReader)

	return ctx.JSON(http.StatusOK, PreviewResponse{
		Title:       title,
		Description: description,
	})
}

// parseAndValidateURL checks the URL format and ensures it is a safe external HTTP/HTTPS URL.
func parseAndValidateURL(rawURL string) (*url.URL, error) {
	parsed, err := url.Parse(rawURL)
	if err != nil {
		return nil, fmt.Errorf("Invalid URL format")
	}

	if parsed.Scheme != "http" && parsed.Scheme != "https" {
		return nil, fmt.Errorf("Only HTTP/HTTPS URLs are allowed")
	}

	// Reject URLs with embedded userinfo (e.g., user:password@host)
	if parsed.User != nil {
		return nil, fmt.Errorf("Credentials in URL are forbidden")
	}

	// Host must be present
	if parsed.Host == "" {
		return nil, fmt.Errorf("Empty host")
	}

	return parsed, nil
}

// publicOnlyDialContext returns a DialContext function that resolves the host,
// rejects any private/reserved IPs, and connects to a safe public IP.
func publicOnlyDialContext() func(ctx context.Context, network, addr string) (net.Conn, error) {
	return func(ctx context.Context, network, addr string) (net.Conn, error) {
		host, port, err := net.SplitHostPort(addr)
		if err != nil {
			return nil, fmt.Errorf("invalid address: %w", err)
		}

		ips, err := net.DefaultResolver.LookupIPAddr(ctx, host)
		if err != nil {
			return nil, fmt.Errorf("DNS resolution failed: %w", err)
		}
		if len(ips) == 0 {
			return nil, fmt.Errorf("no IP addresses found for %s", host)
		}

		var chosen net.IPAddr
		for _, ip := range ips {
			if !isPublicIP(ip.IP) {
				return nil, fmt.Errorf("private/reserved IP address forbidden: %s", ip.IP)
			}
			// Prefer IPv4
			if chosen.IP == nil || (chosen.IP.To4() == nil && ip.IP.To4() != nil) {
				chosen = ip
			}
		}

		if chosen.IP == nil {
			return nil, fmt.Errorf("no public IP found")
		}

		// Dial directly to the chosen safe IP
		dialer := net.Dialer{}
		return dialer.DialContext(ctx, network, net.JoinHostPort(chosen.IP.String(), port))
	}
}

// isPublicIP reports whether the IP is not private, loopback, link‑local,
// multicast, or unspecified.
func isPublicIP(ip net.IP) bool {
	if ip == nil {
		return false
	}
	ip = ip.To4()
	if ip == nil {
		// For IPv6 we still rely on the standard checks
		ip = ip.To16()
	}
	return !ip.IsUnspecified() &&
		!ip.IsLoopback() &&
		!ip.IsPrivate() &&
		!ip.IsLinkLocalUnicast() &&
		!ip.IsLinkLocalMulticast() &&
		!ip.IsMulticast()
}

// extractTitleAndDescription parses HTML and returns the page title and meta description.
func extractTitleAndDescription(r io.Reader) (string, string) {
	z := html.NewTokenizer(r)
	var title, description string

	for {
		tt := z.Next()
		if tt == html.ErrorToken {
			break
		}

		// Early exit when both values are found
		if title != "" && description != "" {
			break
		}

		switch tt {
		case html.StartTagToken, html.SelfClosingTagToken:
			tagName, _ := z.TagName()
			tagStr := string(tagName)

			if tagStr == "title" {
				// Accumulate text until the closing </title> tag
				for {
					tt = z.Next()
					if tt == html.ErrorToken {
						break
					}
					if tt == html.EndTagToken {
						endTag, _ := z.TagName()
						if string(endTag) == "title" {
							break
						}
					}
					if tt == html.TextToken {
						title += string(z.Text())
					}
				}
			}

			if tagStr == "meta" {
				var name, content string
				for {
					key, val, more := z.TagAttr()
					attrKey := string(key)
					if attrKey == "name" {
						name = string(val)
					}
					if attrKey == "content" {
						content = string(val)
					}
					if !more {
						break
					}
				}
				if name == "description" {
					description = content
				}
			}
		}
	}

	return title, description
}

