// FetchURLPreview handles the /preview POST endpoint.
// It expects JSON body: {"url": "..."}
// It fetches the URL, extracts the page title and meta description,
// and returns them as JSON.
func FetchURLPreview(c echo.Context) error {
	var req struct {
		URL string `json:"url"`
	}
	if err := c.Bind(&req); err != nil {
		return c.JSON(http.StatusBadRequest, map[string]string{
			"error": "Invalid request body",
		})
	}
	if req.URL == "" {
		return c.JSON(http.StatusBadRequest, map[string]string{
			"error": "Missing 'url' field",
		})
	}

	// Create an HTTP client with a 3-second timeout.
	client := &http.Client{
		Timeout: 3 * time.Second,
	}
	resp, err := client.Get(req.URL)
	if err != nil {
		return c.JSON(http.StatusOK, map[string]string{
			"title":       "",
			"description": "",
			"error":       "Failed to fetch URL: " + err.Error(),
		})
	}
	defer resp.Body.Close()

	// Optionally check for a successful status code.
	if resp.StatusCode != http.StatusOK {
		return c.JSON(http.StatusOK, map[string]string{
			"title":       "",
			"description": "",
			"error":       "Unexpected status code: " + resp.Status,
		})
	}

	// Extract metadata from the HTML.
	title, description := extractMeta(resp.Body)

	return c.JSON(http.StatusOK, map[string]string{
		"title":       title,
		"description": description,
	})
}

// extractMeta parses HTML from the reader and returns the title and
// the content of the meta description tag.
func extractMeta(r io.Reader) (title, description string) {
	tokenizer := html.NewTokenizer(r)
	for {
		tt := tokenizer.Next()
		switch tt {
		case html.ErrorToken:
			return title, description
		case html.StartTagToken, html.SelfClosingTagToken:
			tagName, hasAttr := tokenizer.TagName()
			if string(tagName) == "title" {
				// Advance to the text node inside <title>
				tokenizer.Next()
				if tokenizer.Token().Type == html.TextToken {
					title = string(tokenizer.Text())
				}
				continue
			}
			if string(tagName) == "meta" && hasAttr {
