// FetchURLPreview handles the /preview endpoint.
// It fetches the given URL, extracts the page title and meta description,
// and returns them as JSON. The implementation includes multiple security
// measures: SSRF prevention (blocks internal/private IPs and hosts),
// redirect protection, response size limit, and timeouts.
func FetchURLPreview(ctx echo.Context) error {
	req := new(PreviewRequest)
	if err := ctx.Bind(req); err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Invalid JSON"})
	}

	// Validate URL format and scheme
	parsedURL, err := url.Parse(req.URL)
	if err != nil || parsedURL.Scheme == "" || parsedURL.Host == "" {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Invalid URL format"})
	}
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Only HTTP/HTTPS URLs are allowed"})
	}

	// Create a context with timeout for the whole operation
	reqCtx, cancel := context.WithTimeout(ctx.Request().Context(), 10*time.Second)
	defer cancel()

	// Check that the initial host resolves to public IP(s) only
	if ok, err := isPublicHost(reqCtx, parsedURL.Host); err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to validate host"})
	} else if !ok {
		return ctx.JSON(http.StatusForbidden, map[string]string{"error": "Internal/non-public hosts are not allowed"})
	}

	// HTTP client with redirect policy that checks each redirect destination
	client := &http.Client{
		Timeout: 10 * time.Second,
		CheckRedirect: func(r *http.Request, via []*http.Request) error {
			// Limit number of redirects
			if len(via) >= 3 {
				return fmt.Errorf("too many redirects")
			}
			// Validate the redirect URL's host
			if ok, err := isPublicHost(reqCtx, r.URL.Host); err != nil {
				return err
			} else if !ok {
				return fmt.Errorf("redirect to internal host is not allowed")
			}
			return nil
		},
	}

	// Create request with the context and proper headers
	httpReq, err := http.NewRequestWithContext(reqCtx, http.MethodGet, req.URL, nil)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to create request"})
	}
	httpReq.Header.Set("User-Agent", "Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	resp, err := client.Do(httpReq)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to fetch URL"})
	}
	defer resp.Body.Close()

	// We accept only HTTP 200 OK
	if resp.StatusCode != http.StatusOK {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": fmt.Sprintf("HTTP %d", resp.StatusCode)})
	}

	// Read up to 1 MB of the response body to avoid memory exhaustion
	const maxBodySize = 1 << 20 // 1 MB
	limitedReader := io.LimitReader(resp.Body, maxBodySize)
	body, err := io.ReadAll(limitedReader)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to read response body"})
	}

	title, description := extractTitleAndDescription(body)

	return ctx.JSON(http.StatusOK, PreviewResponse{
		Title:       title,
		Description: description,
	})
}

// isPublicHost returns true if the given host (which can be an IP or a domain
// name) resolves exclusively to global unicast IP addresses. This prevents
// SSRF attacks targeting internal/private networks.
func isPublicHost(ctx context.Context, host string) (bool, error) {
	// If host is already an IP, check it directly
	if ip := net.ParseIP(host); ip != nil {
		return ip.IsGlobalUnicast(), nil
	}

	// Resolve hostname to IPs
	ips, err := net.DefaultResolver.LookupIPAddr(ctx, host)
	if err != nil {
		return false, err
	}

	for _, ia := range ips {
		if !ia.IP.IsGlobalUnicast() {
			return false, nil
		}
	}
	return true, nil
}

