package main

import (
	"bytes"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"strings"
	"time"

	"github.com/labstack/echo/v4"
	"golang.org/x/net/html"
)

// PreviewRequest is the expected JSON body.
type PreviewRequest struct {
	URL string `json:"url"`
}

// PreviewResponse is the JSON response.
type PreviewResponse struct {
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
}

// FetchURLPreview handles the /preview endpoint.
func FetchURLPreview(ctx echo.Context) error {
	req := new(PreviewRequest)
	if err := ctx.Bind(req); err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Invalid JSON"})
	}

	parsedURL, err := url.Parse(req.URL)
	if err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Invalid URL format"})
	}

	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Only HTTP/HTTPS URLs are allowed"})
	}

	// Resolve host and block private / loopback IPs (SSRF prevention)
	host := parsedURL.Hostname()
	if host == "" {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Invalid URL: missing host"})
	}
	if err := isPublicHost(host); err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": err.Error()})
	}

	// Custom transport with secure dial and response size limit
	transport := &http.Transport{
		DialContext:           safeDialContext(),
		ForceAttemptHTTP2:     true,
		MaxIdleConns:          10,
		IdleConnTimeout:       30 * time.Second,
		DisableCompression:    true,
		ResponseHeaderTimeout: 3 * time.Second,
	}
	client := &http.Client{
		Transport: transport,
		Timeout:   5 * time.Second,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if len(via) >= 10 {
				return fmt.Errorf("too many redirects")
			}
			// Validate redirect URL
			redirectURL := req.URL
			if redirectURL.Scheme != "http" && redirectURL.Scheme != "https" {
				return fmt.Errorf("redirect to non-HTTP/HTTPS is forbidden")
			}
			if err := isPublicHost(redirectURL.Hostname()); err != nil {
				return fmt.Errorf("redirect to private/internal host is forbidden")
			}
			return nil
		},
	}

	// Build request with timeout-aware context from echo
	httpReq, err := http.NewRequestWithContext(ctx.Request().Context(), http.MethodGet, parsedURL.String(), nil)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to create request"})
	}
	httpReq.Header.Set("User-Agent", "Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	resp, err := client.Do(httpReq)
	if err != nil {
		return ctx.JSON(http.StatusBadGateway, map[string]string{"error": "Failed to fetch URL"})
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return ctx.JSON(http.StatusBadGateway, map[string]string{"error": fmt.Sprintf("HTTP %d", resp.StatusCode)})
	}

	// Limit response body to 1MB
	const maxBodySize = 1 << 20 // 1 MB
	limitedReader := io.LimitReader(resp.Body, maxBodySize)
	body, err := io.ReadAll(limitedReader)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to read response body"})
	}

	title, description := extractTitleAndDescription(body)

	return ctx.JSON(http.StatusOK, PreviewResponse{
		Title:       title,
		Description: description,
	})
}

// safeDialContext returns a DialContext function that checks if the resolved IP is public.
func safeDialContext() func(ctx context.Context, network, addr string) (net.Conn, error) {
	return func(ctx context.Context, network, addr string) (net.Conn, error) {
		host, port, err := net.SplitHostPort(addr)
		if err != nil {
			return nil, err
		}
		ips, err := net.DefaultResolver.LookupIPAddr(ctx, host)
		if err != nil {
			return nil, err
		}
		for _, ip := range ips {
			if !isPublicIP(ip.IP) {
				return nil, fmt.Errorf("connection to private/internal IP is forbidden")
			}
		}
		dialer := &net.Dialer{Timeout: 3 * time.Second}
		return dialer.DialContext(ctx, network, net.JoinHostPort(host, port))
	}
}

// isPublicHost checks if the hostname resolves to at least one public IP.
func isPublicHost(host string) error {
	// If host is an IP already, check it directly
	if ip := net.ParseIP(host); ip != nil {
		if !isPublicIP(ip) {
			return fmt.Errorf("cannot fetch private or internal IP addresses")
		}
		return nil
	}
	// Resolve host (blocking)
	ips, err := net.LookupIP(host)
	if err != nil {
		return fmt.Errorf("cannot resolve host: %w", err)
	}
	for _, ip := range ips {
		if isPublicIP(ip) {
			return nil // at least one public IP is okay
		}
	}
	return fmt.Errorf("hostname resolves to private/internal IP")
}

// isPublicIP returns true if the IP is not a loopback, private, link-local, or unspecified address.
func isPublicIP(ip net.IP) bool {
	if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsUnspecified() {
		return false
	}
	if ip.To4() != nil {
		return true
	}
	// IPv6: also consider Unique Local Addresses (fc00::/7) as private
	if ip.To16() != nil && (ip[0] == 0xfc || ip[0] == 0xfd) {
		return false
	}
	return true
}

// extractTitleAndDescription extracts the title and meta description from HTML content.
func extractTitleAndDescription(htmlContent []byte) (string, string) {
	tokenizer := html.NewTokenizer(bytes.NewReader(htmlContent))
	var title, description string
	inTitle := false

	for {
		tokenType := tokenizer.Next()
		switch tokenType {
		case html.ErrorToken:
			return strings.TrimSpace(title), strings.TrimSpace(description)
		case html.StartTagToken, html.SelfClosingTagToken:
			tagName, hasAttr := tokenizer.TagName()
			if bytes.Equal(tagName, []byte("title")) {
				inTitle = true
			} else if bytes.Equal(tagName, []byte("meta")) && hasAttr {
				var name, content string
				for {
					key, val, more := tokenizer.TagAttr()
					if bytes.Equal(key, []byte("name")) {
						name = string(val)
					} else if bytes.Equal(key, []byte("content")) {
						content = string(val)
					}
					if !more {
						break
					}
				}
				if strings.EqualFold(name, "description") && description == "" {
					description = content
				}
			}
		case html.TextToken:
			if inTitle {
				title = string(tokenizer.Text())
				inTitle = false
			}
		}
	}
}

