func main() {
	e := echo.New()
	e.POST("/preview", FetchURLPreview)
	e.Logger.Fatal(e.Start(":8080"))
}

// FetchURLPreview handles POST /preview.
func FetchURLPreview(c echo.Context) error {
	var req struct {
		URL string `json:"url"`
	}
	if err := c.Bind(&req); err != nil {
		return c.JSON(http.StatusBadRequest, map[string]string{
			"error": "Invalid request body",
		})
	}
	if req.URL == "" {
		return c.JSON(http.StatusBadRequest, map[string]string{
			"error": "URL is required",
		})
	}

	client := &http.Client{
		Timeout: 3 * time.Second,
	}
	resp, err := client.Get(req.URL)
	if err != nil {
		return c.JSON(http.StatusInternalServerError, map[string]string{
			"error": "Failed to fetch URL",
		})
	}
	defer resp.Body.Close()

	doc, err := html.Parse(resp.Body)
	if err != nil {
		return c.JSON(http.StatusInternalServerError, map[string]string{
			"error": "Failed to parse HTML",
		})
	}

	title, description := extractMeta(doc)

	return c.JSON(http.StatusOK, map[string]interface{}{
		"url":         req.URL,
		"title":       title,
		"description": description,
	})
}

// extractMeta traverses the HTML node tree to find the <title> text and
// a <meta name="description"> content attribute.
func extractMeta(n *html.Node) (title, description string) {
	var f func(*html.Node)
	f = func(node *html.Node) {
		if node.Type == html.ElementNode {
			if node.Data == "title" {
				// simple extraction: take the first child text node
				if node.FirstChild != nil && node.FirstChild.Type == html.TextNode {
					title = node.FirstChild.Data
				}
			}
			if node.Data == "meta" {
				var name, content string
				for _, attr := range node.Attr {
					switch attr.Key {
					case "name":
						name = attr.Val
					case "content":
						content = attr.Val
					}
				}
				if name == "description" && content != "" {
					description = content
				}
			}
		}
		for c := node.FirstChild; c != nil; c = c.NextSibling {
			f(c)
		}
	}
	f(n)
	return
}

