	}

	title, description := extractTitleAndDescription(body)

	return ctx.JSON(http.StatusOK, PreviewResponse{
		Title:       title,
		Description: description,
	})
}

// safeDialer resolves the address and ensures none of the resolved IPs are private/internal.
func safeDialer(ctx context.Context, network, addr string) (net.Conn, error) {
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, fmt.Errorf("invalid address: %w", err)
	}

	resolver := net.Resolver{}
	ips, err := resolver.LookupIPAddr(ctx, host)
	if err != nil {
		return nil, fmt.Errorf("failed to resolve host %s: %w", host, err)
	}
	if len(ips) == 0 {
		return nil, fmt.Errorf("no IP addresses for host %s", host)
	}

	// Collect safe IPs
	var safeIPs []net.IP
	for _, ia := range ips {
		if !isUnsafeIP(ia.IP) {
			safeIPs = append(safeIPs, ia.IP)
		}
	}
	if len(safeIPs) == 0 {
		return nil, fmt.Errorf("host %s resolves only to internal/private IPs", host)
	}

	// Directly dial the safe IPs (prevents DNS rebinding via TOCTOU)
	dialer := net.Dialer{}
	for _, ip := range safeIPs {
		conn, err := dialer.DialContext(ctx, network, net.JoinHostPort(ip.String(), port))
		if err == nil {
			return conn, nil
		}
	}
	return nil, fmt.Errorf("failed to connect to %s", addr)
}

// isUnsafeIP checks if an IP address is prohibited (private, loopback, link-local, multicast, etc.)
func isUnsafeIP(ip net.IP) bool {
	if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsUnspecified() || ip.IsMulticast() {
		return true
	}

	// IPv4-specific checks
	if ip4 := ip.To4(); ip4 != nil {
		// 0.0.0.0/8 (reserved)
		if ip4[0] == 0 {
			return true
		}
		// 100.64.0.0/10 (shared address space, RFC 6598)
		if ip4[0] == 100 && ip4[1]&0xC0 == 64 {
			return true
		}
		// 240.0.0.0/4 (reserved/experimental)
		if ip4[0] >= 240 {
			return true
		}
	}

	return false
}

// extractTitleAndDescription parses HTML and returns the title and meta description.
func extractTitleAndDescription(htmlContent []byte) (string, string) {
	z := html.NewTokenizer(bytes.NewReader(htmlContent))
	var title, description string
	inTitle := false

	for {
		tokenType := z.Next()
		if tokenType == html.ErrorToken {
			break
		}
		switch tokenType {
		case html.StartTagToken, html.SelfClosingTagToken:
			name, hasAttr := z.TagName()
			tagName := string(name)
			if tagName == "title" {
				inTitle = true
				continue
			}
			if tagName == "meta" && hasAttr {
				var attrName, content string
				for {
					key, val, more := z.TagAttr()
					if strings.EqualFold(string(key), "name") {
						attrName = string(val)
					} else if strings.EqualFold(string(key), "content") {
						content = string(val)
					}
					if !more {
						break
					}
				}
				if strings.EqualFold(attrName, "description") && content != "" {
					description = content
				}
			}
		case html.TextToken:
			if inTitle {
				title = string(z.Text())
				inTitle = false
			}
		case html.EndTagToken:
			name, _ := z.TagName()
			if string(name) == "title" {
				inTitle = false
			}
		}
	}
	return title, description
}

