// Request payload
type URLRequest struct {
	URL string `json:"url"`
}

// Response payload
type URLPreview struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

func FetchURLPreview(c echo.Context) error {
	var req URLRequest
	if err := c.Bind(&req); err != nil {
		return c.JSON(http.StatusBadRequest, map[string]string{
			"error": "invalid request body",
		})
	}

	if req.URL == "" {
		return c.JSON(http.StatusBadRequest, map[string]string{
			"error": "url is required",
		})
	}

	// Fetch the URL with a 3-second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}
	resp, err := client.Get(req.URL)
	if err != nil {
		return c.JSON(http.StatusBadGateway, map[string]string{
			"error": fmt.Sprintf("failed to fetch url: %v", err),
		})
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return c.JSON(http.StatusBadGateway, map[string]string{
			"error": fmt.Sprintf("received non-200 status: %d", resp.StatusCode),
		})
	}

	// Read a limited portion of the body to avoid huge downloads (optional)
	// but we'll read fully for proper parsing.
	doc, err := html.Parse(resp.Body)
	if err != nil {
		return c.JSON(http.StatusInternalServerError, map[string]string{
			"error": "failed to parse HTML",
		})
	}

	title, description := extractMeta(doc)

	return c.JSON(http.StatusOK, URLPreview{
		Title:       title,
		Description: description,
	})
}

// extractMeta walks the HTML node tree and extracts <title> and meta description.
func extractMeta(n *html.Node) (title, description string) {
	var crawler func(*html.Node)
	crawler = func(node *html.Node) {
		if node.Type == html.ElementNode {
			if node.Data == "title" {
				// Get the text content of <title>
				if node.FirstChild != nil {
					title = node.FirstChild.Data
				}
			}
			if node.Data == "meta" {
				var name, content string
				for _, attr := range node.Attr {
					if attr.Key == "name" && strings.ToLower(attr.Val) == "description" {
						name = attr.Val
					}
					if attr.Key == "content" {
						content = attr.Val
					}
				}
				if name != "" && content != "" {
					description = content
				}
			}
		}
		for child := node.FirstChild; child != nil; child = child.NextSibling {
			crawler(child)
		}
	}
	crawler(n)
	return
}

func main() {
