package main

import (
    "net/http"
    "strings"
    "time"

    "github.com/labstack/echo/v4"
    "golang.org/x/net/html"
)

func main() {
    e := echo.New()
    e.POST("/preview", FetchURLPreview)
    e.Start(":8080")
}

type fetchRequest struct {
    URL string `json:"url"`
}

type fetchResponse struct {
    Title       string `json:"title"`
    Description string `json:"description"`
}

type errorResponse struct {
    Error string `json:"error"`
}

// FetchURLPreview is a handler that receives a POST request with a JSON body
// containing a "url" field. It fetches the content from the provided URL,
// parses the HTML to extract the page title and meta description,
// and returns a JSON response with the result.
func FetchURLPreview(c echo.Context) error {
    var req fetchRequest
    if err := c.Bind(&req); err != nil {
        return c.JSON(http.StatusBadRequest, errorResponse{Error: "Invalid request body"})
    }
    if req.URL == "" {
        return c.JSON(http.StatusBadRequest, errorResponse{Error: "URL is required"})
    }

    client := &http.Client{
        Timeout: 3 * time.Second,
    }

    resp, err := client.Get(req.URL)
    if err != nil {
        return c.JSON(http.StatusInternalServerError, errorResponse{Error: "Failed to fetch URL: " + err.Error()})
    }
    defer resp.Body.Close()

    doc, err := html.Parse(resp.Body)
    if err != nil {
        return c.JSON(http.StatusInternalServerError, errorResponse{Error: "Failed to parse HTML: " + err.Error()})
    }

    title, description := extractMeta(doc)
    return c.JSON(http.StatusOK, fetchResponse{
        Title:       title,
        Description: description,
    })
}

// extractMeta traverses the HTML node tree and extracts the first title text
// and the first <meta name="description"> content attribute.
func extractMeta(n *html.Node) (title, description string) {
    var f func(*html.Node)
    f = func(n *html.Node) {
        if n.Type == html.ElementNode {
            if n.Data == "title" && title == "" {
                if n.FirstChild != nil {
                    title = n.FirstChild.Data
                }
            }
            if n.Data == "meta" && description == "" {
                var name, content string
                for _, attr := range n.Attr {
                    if attr.Key == "name" {
                        name = attr.Val
                    }
                    if attr.Key == "content" {
                        content = attr.Val
                    }
                }
                if strings.EqualFold(name, "description") {
                    description = content
                }
            }
        }
        for c := n.FirstChild; c != nil; c = c.NextSibling {
            f(c)
        }
    }
    f(n)
    return
}

