	"time"

	"github.com/labstack/echo/v4"
	"golang.org/x/net/html"
)

// PreviewRequest is the expected JSON body for the /preview endpoint.
type PreviewRequest struct {
	URL string `json:"url"`
}

// PreviewResponse contains the extracted title and description from the target page.
type PreviewResponse struct {
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
}

// FetchURLPreview handles the POST /preview route. It fetches the given URL,
// validates it against SSRF and other attacks, and extracts the page title
// and meta description.
func FetchURLPreview(ctx echo.Context) error {
	req := new(PreviewRequest)
	if err := ctx.Bind(req); err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Invalid JSON"})
	}

	// ---------- URL validation ----------
	parsedURL, err := url.Parse(req.URL)
	if err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Invalid URL format"})
	}
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Only HTTP/HTTPS URLs are allowed"})
	}
	if parsedURL.Host == "" {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "URL must contain a host"})
	}
	if parsedURL.User != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "URLs with credentials are not allowed"})
	}

	// ---------- DNS resolution & IP whitelist (SSRF prevention) ----------
	hostname := parsedURL.Hostname()
	ips, err := net.LookupIP(hostname)
	if err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Failed to resolve host"})
	}
	if len(ips) == 0 {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "No IP addresses found for host"})
	}
	for _, ip := range ips {
		if !isPublicIP(ip) {
			return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Host resolves to a private/internal IP address"})
		}
	}

	// Use the first resolved IP for the actual connection (prevents DNS rebinding later)
	targetIP := ips[0]
	port := parsedURL.Port()
	if port == "" {
		if parsedURL.Scheme == "https" {
			port = "443"
		} else {
			port = "80"
		}
	}
	originalHost := hostname

	// ---------- Custom HTTP client with fixed IP & no redirects ----------
	dialer := &net.Dialer{
		Timeout:   5 * time.Second,
		KeepAlive: 5 * time.Second,
	}

	transport := &http.Transport{
		// For plain HTTP connections, dial directly to the pre-resolved IP.
		DialContext: func(dialCtx context.Context, network, addr string) (net.Conn, error) {
			return dialer.DialContext(dialCtx, network, net.JoinHostPort(targetIP.String(), port))
		},
		// For HTTPS, we also need to set the correct SNI (ServerName) so the TLS handshake succeeds.
		DialTLSContext: func(dialCtx context.Context, network, addr string) (net.Conn, error) {
			conn, err := dialer.DialContext(dialCtx, network, net.JoinHostPort(targetIP.String(), port))
			if err != nil {
				return nil, err
			}
			tlsConfig := &tls.Config{
				ServerName: originalHost,
				MinVersion: tls.VersionTLS12,
			}
			tlsConn := tls.Client(conn, tlsConfig)
			if err := tlsConn.HandshakeContext(dialCtx); err != nil {
				conn.Close()
				return nil, err
			}
			return tlsConn, nil
		},
		DisableKeepAlives: true,
	}

	client := &http.Client{
		Transport: transport,
		Timeout:   10 * time.Second,
		// We do NOT follow redirects. This avoids any redirect‑based SSRF attacks.
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			return http.ErrUseLastResponse
		},
	}

	// ---------- Create and execute the request ----------
	httpReq, err := http.NewRequestWithContext(ctx.Request().Context(), http.MethodGet, parsedURL.String(), nil)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to create request"})
	}
	httpReq.Header.Set("User-Agent", "Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	resp, err := client.Do(httpReq)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to fetch URL"})
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": fmt.Sprintf("HTTP %d", resp.StatusCode)})
	}

	// ---------- Content-Type check to avoid parsing non‑HTML content ----------
	contentType := resp.Header.Get("Content-Type")
	if !strings.Contains(contentType, "text/html") {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "URL does not point to HTML content"})
	}

