import (
    "io"
    "net/http"
    "strings"
    "time"

    "github.com/labstack/echo/v4"
    "golang.org/x/net/html"
)

type Request struct {
    URL string `json:"url"`
}

type Preview struct {
    Title       string `json:"title"`
    Description string `json:"description"`
}

func main() {
    e := echo.New()
    e.POST("/preview", FetchURLPreview)
    e.Logger.Fatal(e.Start(":1323"))
}

// FetchURLPreview handles POST /preview, fetches the given URL,
// extracts title and meta description, and returns a JSON preview.
func FetchURLPreview(ctx echo.Context) error {
    var req Request
    if err := ctx.Bind(&req); err != nil {
        return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "invalid request"})
    }
    if req.URL == "" {
        return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "url is required"})
    }

    client := &http.Client{
        Timeout: 3 * time.Second,
    }

    resp, err := client.Get(req.URL)
    if err != nil {
        return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "failed to fetch url"})
    }
    defer resp.Body.Close()

    if resp.StatusCode != http.StatusOK {
        return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "non-200 status code"})
    }

    body, err := io.ReadAll(resp.Body)
    if err != nil {
        return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "failed to read body"})
    }

    doc, err := html.Parse(strings.NewReader(string(body)))
    if err != nil {
        return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "failed to parse html"})
    }

    title, desc := extractMetadata(doc)

    preview := Preview{
        Title:       title,
        Description: desc,
    }
    return ctx.JSON(http.StatusOK, preview)
}

// extractMetadata recursively walks the HTML node tree to find the <title> content
// and the first <meta name="description"> content.
func extractMetadata(n *html.Node) (title, description string) {
    var f func(*html.Node)
    f = func(n *html.Node) {
        if n.Type == html.ElementNode {
            if n.Data == "title" {
                if n.FirstChild != nil {
                    title = n.FirstChild.Data
                }
            } else if n.Data == "meta" {
                var name, content string
                for _, attr := range n.Attr {
                    if attr.Key == "name" {
                        name = attr.Val
                    } else if attr.Key == "content" {
                        content = attr.Val
                    }
                }
                if name == "description" && content != "" {
                    description = content
                }
            }
        }
        for c := n.FirstChild; c != nil; c = c.NextSibling {
            f(c)
        }
    }
    f(n)
    return
}

