// safeDialContext resolves the host and checks every resolved IP address
// against disallowed ranges (private, loopback, link-local, unspecified, multicast)
// and the well-known cloud metadata IP. If any IP is disallowed the connection fails.
func safeDialContext(ctx context.Context, network, addr string) (net.Conn, error) {
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, fmt.Errorf("invalid address %q: %w", addr, err)
	}

	ips, err := net.DefaultResolver.LookupIPAddr(ctx, host)
	if err != nil {
		return nil, fmt.Errorf("DNS lookup failed for %q: %w", host, err)
	}
	if len(ips) == 0 {
		return nil, fmt.Errorf("no IP addresses found for %q", host)
	}

	for _, ip := range ips {
		if isPrivateIP(ip.IP) {
			return nil, fmt.Errorf("private or disallowed IP address: %s", ip.IP)
		}
	}

	// Create a fresh dialer and connect to the first resolved IP.
	// Using the IP directly prevents DNS rebinding between check and connect.
	d := net.Dialer{}
	return d.DialContext(ctx, network, net.JoinHostPort(ips[0].IP.String(), port))
}

// isPrivateIP checks if the given IP is in a range that should not be
// accessible from the server (RFC 1918, loopback, link-local, etc).
func isPrivateIP(ip net.IP) bool {
	// Check IPv4 and IPv6 special addresses.
	if ip.IsLoopback() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() ||
		ip.IsPrivate() || ip.IsUnspecified() || ip.IsMulticast() {
		return true
	}

	// Explicitly block the AWS / cloud metadata endpoint (169.254.169.254).
	if ip.To4() != nil {
		if ip.To4().String() == "169.254.169.254" {
			return true
		}
	}

	// Additional checks can be added (e.g., IPv6 unique local fc00::/7).
	return false
}

// extractTitleAndDescription parses HTML content and returns the page title
// and the content of a <meta name="description"> tag.
func extractTitleAndDescription(htmlContent []byte) (string, string) {
	z := html.NewTokenizer(bytes.NewReader(htmlContent))
	var title, description string
	inTitle := false

	for {
		tt := z.Next()
		if tt == html.ErrorToken {
			break
		}
		switch tt {
		case html.StartTagToken, html.SelfClosingTagToken:
			tagName, hasAttr := z.TagName()
			if string(tagName) == "title" {
				inTitle = true
			} else if bytes.Equal(tagName, []byte("meta")) && hasAttr {
				var name, content string
				for {
					key, val, more := z.TagAttr()
					if bytes.Equal(key, []byte("name")) && bytes.Equal(val, []byte("description")) {
						name = string(val)
					}
					if bytes.Equal(key, []byte("content")) {
						content = string(val)
					}
					if !more {
						break
					}
				}
				if name == "description" && content != "" {
					description = content
				}
			}
		case html.TextToken:
			if inTitle {
				title = string(z.Text())
				inTitle = false
			}
		}
		// Exit early if we already have both values.
		if title != "" && description != "" {
			break
		}
	}
	return title, description
}

