// FetchURLPreview handles POST /preview. It fetches the given URL,
// extracts the page title and meta description, and returns them as JSON.
func FetchURLPreview(ctx echo.Context) error {
    var req PreviewRequest
    if err := ctx.Bind(&req); err != nil {
        return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Invalid request"})
    }
    if req.URL == "" {
        return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "URL is required"})
    }

    client := &http.Client{
        Timeout: 3 * time.Second,
    }
    resp, err := client.Get(req.URL)
    if err != nil {
        return ctx.JSON(http.StatusBadGateway, map[string]string{"error": "Failed to fetch URL: " + err.Error()})
    }
    defer resp.Body.Close()
    if resp.StatusCode < 200 || resp.StatusCode >= 400 {
        return ctx.JSON(http.StatusBadGateway, map[string]string{"error": "URL returned non-OK status"})
    }

    body, err := io.ReadAll(resp.Body)
    if err != nil {
        return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to read response body"})
    }

    doc, err := html.Parse(strings.NewReader(string(body)))
    if err != nil {
        return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to parse HTML"})
    }

    title := findTitle(doc)
    description := findMetaDescription(doc)

    return ctx.JSON(http.StatusOK, PreviewResponse{
        Title:       title,
        Description: description,
    })
}

// findTitle recursively searches for the first <title> element and returns its text content.
func findTitle(n *html.Node) string {
    if n.Type == html.ElementNode && n.Data == "title" {
        return extractText(n)
    }
    for c := n.FirstChild; c != nil; c = c.NextSibling {
        if title := findTitle(c); title != "" {
            return title
        }
    }
    return ""
}

// findMetaDescription recursively searches for a <meta name="description"> tag and returns its content attribute.
func findMetaDescription(n *html.Node) string {
    if n.Type == html.ElementNode && n.Data == "meta" {
        var name, content string
        for _, a := range n.Attr {
            if a.Key == "name" {
                name = a.Val
            } else if a.Key == "content" {
                content = a.Val
            }
        }
        if strings.ToLower(name) == "description" && content != "" {
            return content
        }
    }
    for c := n.FirstChild; c != nil; c = c.NextSibling {
        if desc := findMetaDescription(c); desc != "" {
            return desc
        }
    }
    return ""
}

// extractText returns all text contained in the subtree rooted at n.
func extractText(n *html.Node) string {
    var sb strings.Builder
    var f func(*html.Node)
    f = func(node *html.Node) {
        if node.Type == html.TextNode {
            sb.WriteString(node.Data)
        }
        for c := node.FirstChild; c != nil; c = c.NextSibling {
            f(c)
        }
    }
    f(n)
    return strings.TrimSpace(sb.String())
}

