	"github.com/PuerkitoBio/goquery"
	"github.com/labstack/echo/v4"
)

// URLPreviewRequest represents the expected JSON body.
type URLPreviewRequest struct {
	URL string `json:"url"`
}

// URLPreviewResponse contains the extracted preview data.
type URLPreviewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

func main() {
	e := echo.New()
	e.POST("/preview", FetchURLPreview)
	e.Logger.Fatal(e.Start(":8080"))
}

// FetchURLPreview handles the POST /preview endpoint.
// It fetches the provided URL, extracts the page title and meta description,
// and returns them as JSON.
func FetchURLPreview(ctx echo.Context) error {
	// Parse request body
	var req URLPreviewRequest
	if err := json.NewDecoder(ctx.Request().Body).Decode(&req); err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{
			"error": "Invalid request body",
		})
	}

	// Validate URL presence
	if strings.TrimSpace(req.URL) == "" {
		return ctx.JSON(http.StatusBadRequest, map[string]string{
			"error": "url field is required",
		})
	}

