// validateURL performs SSRF-safe validation:
// - ensures scheme is http/https
// - resolves hostname and checks that no IP belongs to a private or reserved range
func validateURL(rawURL string) error {
    parsed, err := url.Parse(rawURL)
    if err != nil {
        return fmt.Errorf("invalid URL format")
    }
    if parsed.Scheme != "http" && parsed.Scheme != "https" {
        return fmt.Errorf("only HTTP/HTTPS URLs are allowed")
    }
    host := parsed.Hostname()
    if host == "" {
        return fmt.Errorf("missing host in URL")
    }

    // Check if host is an IP address directly
    ip := net.ParseIP(host)
    if ip != nil {
        if isRestrictedIP(ip) {
            return fmt.Errorf("URL points to a forbidden IP address")
        }
        return nil
    }

    // Otherwise resolve DNS and check all resolved addresses
    ips, err := net.LookupIP(host)
    if err != nil {
        return fmt.Errorf("failed to resolve host: %w", err)
    }
    for _, ip := range ips {
        if isRestrictedIP(ip) {
            return fmt.Errorf("URL points to a forbidden IP address")
        }
    }
    return nil
}

// isRestrictedIP returns true if the IP is in a private, loopback,
// link-local, or otherwise reserved range that should not be accessed.
func isRestrictedIP(ip net.IP) bool {
    return ip.IsLoopback() ||
        ip.IsPrivate() ||
        ip.IsLinkLocalUnicast() ||
        ip.IsLinkLocalMulticast() ||
        ip.IsUnspecified() ||
        ip.IsMulticast()
}

// extractTitleAndDescription parses HTML content to find the page title
// and meta description. Returns empty strings if not found.
func extractTitleAndDescription(htmlContent []byte) (string, string) {
    reader := strings.NewReader(string(htmlContent))
    tokenizer := html.NewTokenizer(reader)

    var title, description string
    inTitle := false

    for {
        tt := tokenizer.Next()
        switch tt {
        case html.ErrorToken:
            // end of document or error
            return title, description
        case html.StartTagToken, html.SelfClosingTagToken:
            tn, hasAttr := tokenizer.TagName()
            tagName := string(tn)

            if tagName == "title" {
                inTitle = true
            } else if tagName == "meta" && hasAttr {
                // Check for name="description"
                var name, content string
                for {
                    key, val, more := tokenizer.TagAttr()
                    attrKey := string(key)
                    attrVal := string(val)
                    if attrKey == "name" {
                        name = attrVal
                    }
                    if attrKey == "content" {
                        content = attrVal
                    }
                    if !more {
                        break
                    }
                }
                if strings.ToLower(name) == "description" && content != "" {
                    description = content
                }
            }
        case html.TextToken:
            if inTitle {
                // Decode text, trim spaces
                title = strings.TrimSpace(string(tokenizer.Text()))
                inTitle = false
            }
        case html.EndTagToken:
            tn, _ := tokenizer.TagName()
            if string(tn) == "title" {
                inTitle = false
            }
        }
    }
}

