// FetchURLPreview handles POST /preview
func FetchURLPreview(ctx echo.Context) error {
	var req fetchRequest
	if err := ctx.Bind(&req); err != nil {
		return echo.NewHTTPError(http.StatusBadRequest, "Invalid request body")
	}

	req.URL = strings.TrimSpace(req.URL)
	if req.URL == "" {
		return echo.NewHTTPError(http.StatusBadRequest, "URL is required")
	}

	// Create HTTP client with 3-second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	resp, err := client.Get(req.URL)
	if err != nil {
		return echo.NewHTTPError(http.StatusBadGateway, "Failed to fetch URL: "+err.Error())
	}
	defer resp.Body.Close()

	if resp.StatusCode >= 400 {
		return echo.NewHTTPError(http.StatusBadGateway, "Remote server returned status: "+resp.Status)
	}

	// Limit the amount of data read to avoid huge responses
	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20)) // 1 MB
	if err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "Failed to read response body")
	}

	title, desc, err := extractMeta(body)
	if err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "Failed to parse HTML")
	}

	return ctx.JSON(http.StatusOK, previewResponse{
		Title:       title,
		Description: desc,
	})
}

// extractMeta parses HTML and returns the title and meta description.
func extractMeta(data []byte) (title, desc string, err error) {
	reader := strings.NewReader(string(data))
	doc, err := html.Parse(reader)
	if err != nil {
		return "", "", err
	}

	var extractor func(*html.Node)
	extractor = func(n *html.Node) {
		if n.Type == html.ElementNode {
			switch n.Data {
			case "title":
				if n.FirstChild != nil {
					title = n.FirstChild.Data
				}
			case "meta":
				var name, content string
				for _, attr := range n.Attr {
					if attr.Key == "name" {
						name = attr.Val
					}
					if attr.Key == "content" {
						content = attr.Val
					}
				}
				if strings.EqualFold(name, "description") && desc == "" {
					desc = content
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			extractor(c)
		}
	}
	extractor(doc)

	return title, desc, nil
}

func main() {
	e := echo.New()
	e.POST("/preview", FetchURLPreview)
	e.Start(":8080")
}

