		return ctx.JSON(http.StatusBadRequest, map[string]string{
			"error": "URL is required",
		})
	}

	client := http.Client{
		Timeout: 3 * time.Second,
	}

	resp, err := client.Get(req.URL)
	if err != nil {
		// Handle timeout or other fetch errors gracefully
		return ctx.JSON(http.StatusBadGateway, map[string]string{
			"error": "Failed to fetch URL: " + err.Error(),
		})
	}
	defer resp.Body.Close()

	bodyBytes, err := io.ReadAll(resp.Body)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{
			"error": "Failed to read response body",
		})
	}
	body := string(bodyBytes)

	title := extractTitle(body)
	description := extractMetaDescription(body)

	return ctx.JSON(http.StatusOK, FetchResponse{
		Title:       title,
		Description: description,
	})
}

func extractTitle(html string) string {
	// Case-insensitive search for <title>...</title>
	re := regexp.MustCompile(`(?i)<title[^>]*>([^<]+)</title>`)
	matches := re.FindStringSubmatch(html)
	if len(matches) > 1 {
		return matches[1]
	}
	return ""
}

func extractMetaDescription(html string) string {
	// Try two common patterns: name="description" followed by content,
	// or content followed by name="description".
	patterns := []string{
		`(?i)<meta[^>]+name=["']description["'][^>]*content=["']([^"']+)["']`,
		`(?i)<meta[^>]+content=["']([^"']+)["'][^>]*name=["']description["']`,
	}

	for _, pattern := range patterns {
		re := regexp.MustCompile(pattern)
		matches := re.FindStringSubmatch(html)
		if len(matches) > 1 {
			return matches[1]
		}
	}
	return ""
}

